<template>
  <section class="legends-page"><div class="legends-container">
    <RouterLink class="back legends-back" to="/">← 返回主页</RouterLink>
    <header class="hero"><p class="eyebrow">Hearthstone Legend Archive</p><h1>炉石传说·上传说记录</h1><p>每个月用什么卡组登上传说。切换模式，回看卡组与职业的更迭。</p></header>
    <section class="summary-grid" aria-label="上传说统计">
      <article class="summary-card latest-card"><span>最近一次上传说</span><strong>{{ latest.label }}</strong><small>{{ latest.modeLabel }} · {{ latest.deck }}<template v-if="latest.hero"> · {{ latest.hero }}</template></small></article>
      <article class="summary-card"><span>上传说记录</span><strong>{{ stats.legends }}</strong><small>狂野 {{ modeCounts.wild }} · 标准 {{ modeCounts.standard }} · 幻变 {{ modeCounts.twist }}</small></article>
      <article class="summary-card"><span>最常用职业</span><strong>{{ stats.favoriteHero || '—' }}</strong><small>{{ stats.favoriteHeroCount }} 次上传说</small></article>
    </section>
    <nav class="mode-tabs" aria-label="模式筛选"><button v-for="mode in tabModes" :key="mode.key" type="button" :class="{ active: selectedMode === mode.key }" @click="selectedMode = mode.key">{{ mode.icon }} {{ mode.label }} <small>{{ mode.key === 'all' ? stats.legends : modeCounts[mode.key] }}</small></button></nav>
    <section class="records-panel"><div class="panel-heading"><div><h2>{{ currentMode.label }}上传说历程</h2><p>只展示上传说的模式；未来空白月份保留为待记录。</p></div><div class="legend"><span class="legend-hit">✦ 已上传说</span></div></div>
      <div class="year-list"><article v-for="year in visibleYears" :key="year" class="year-section"><h3>{{ year }} 年 <small>{{ yearSummary(year) }}</small></h3><div class="month-grid">
        <article v-for="record in recordsForYear(year)" :key="record.month" class="month-card" :class="cardState(record)"><header><span>{{ record.month }} 月</span><em v-if="isRecordLatest(record)">最近</em></header>
          <template v-if="selectedMode === 'all'"><div v-for="mode in visibleModes(record)" :key="mode.key" class="mode-row"><div class="mode-meta"><span class="mode-name" :style="{ '--mode-color': mode.color }">{{ mode.label }}</span><small v-if="record[mode.key].hero">· {{ record[mode.key].hero }}</small></div><b>{{ record[mode.key].deck }}</b></div></template>
          <template v-else><div v-if="record[selectedMode]" class="single-hit"><b>{{ record[selectedMode].deck }}</b><span v-if="record[selectedMode].hero">{{ record[selectedMode].hero }}</span><i :style="{ background: currentMode.color }"></i></div><div v-else class="single-empty">暂无记录</div></template>
        </article>
      </div></article></div>
    </section>
    <section class="records-panel class-panel"><div class="panel-heading"><div><h2>职业上传说次数</h2><p>所有已上传说记录汇总；卡条越长，出现次数越多。</p></div></div><div class="hero-bars"><div v-for="item in stats.heroCounts" :key="item.name" class="hero-bar"><span>{{ item.name }}</span><div><i :style="{ width: `${item.percent}%` }"></i></div><b>{{ item.count }}</b></div></div></section>
  </div></section>
</template>
<script setup>
import { computed, ref } from 'vue'
import { legendRecords, modes } from '../data/legendRecords.js'
const selectedMode = ref('all')
const tabModes = [{ key: 'all', label: '全部模式', icon: '✦' }, ...modes]
const currentMode = computed(() => tabModes.find((mode) => mode.key === selectedMode.value))
const years = [...new Set(legendRecords.map((record) => record.year))].sort((a, b) => b - a)
const recordsForYear = (year) => legendRecords.filter((record) => record.year === year && (selectedMode.value === 'all' || record[selectedMode.value]?.deck))
const visibleYears = computed(() => years.filter((year) => recordsForYear(year).length))
const allEntries = computed(() => legendRecords.flatMap((record) => modes.map((mode) => ({ ...record[mode.key], mode, record })).filter((entry) => entry.deck)))
const modeCounts = computed(() => Object.fromEntries(modes.map((mode) => [mode.key, allEntries.value.filter((entry) => entry.mode.key === mode.key).length])))
const latest = computed(() => { const entry = [...allEntries.value].at(-1); return { label: `${entry.record.year}年${entry.record.month}月`, modeLabel: entry.mode.label, deck: entry.deck, hero: entry.hero } })
const stats = computed(() => { const heroCounts = Object.entries(allEntries.value.reduce((counts, entry) => { if (entry.hero) counts[entry.hero] = (counts[entry.hero] || 0) + 1; return counts }, {})).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count); const max = heroCounts[0]?.count || 1; heroCounts.forEach((item) => { item.percent = item.count / max * 100 }); return { legends: allEntries.value.length, recorded: legendRecords.flatMap((record) => modes.map((mode) => record[mode.key])).filter(Boolean).length, missed: legendRecords.flatMap((record) => modes.map((mode) => record[mode.key])).filter((entry) => entry?.status === 'missed').length, favoriteHero: heroCounts[0]?.name, favoriteHeroCount: heroCounts[0]?.count || 0, heroCounts } })
const visibleModes = (record) => modes.filter((mode) => record[mode.key]?.deck)
const cardState = (record) => modes.some((mode) => record[mode.key]?.deck) ? 'has-record' : ''
const latestKey = `${latest.value.label}-${latest.value.modeLabel}`
const isRecordLatest = (record) => modes.some((mode) => `${record.year}年${record.month}月-${mode.label}` === latestKey)
const yearSummary = (year) => { const entries = recordsForYear(year).flatMap((record) => modes.map((mode) => record[mode.key])).filter((entry) => entry?.deck); return entries.length ? `已上传说 ${entries.length} 次` : '待记录' }
</script>
<style scoped>
