.summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 30px 0 20px; }.summary-card, .records-panel { border: 1px solid rgba(234, 213, 174, .16); border-radius: 14px; background: rgba(26, 28, 43, .82); box-shadow: 0 18px 38px rgba(0, 0, 0, .2); }.summary-card { display: flex; min-height: 118px; padding: 17px; flex-direction: column; }.summary-card span, .summary-card small { color: #aaa5b8; font-size: .86rem; }.summary-card strong { margin: 4px 0; color: #f3d28a; font-size: 1.7rem; line-height: 1.2; }.latest-card { background: linear-gradient(135deg, rgba(102, 72, 184, .5), rgba(30, 37, 59, .92)); }
.mode-tabs { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 20px; }.mode-tabs button { border: 1px solid rgba(255,255,255,.15); border-radius: 999px; padding: 8px 14px; background: rgba(255,255,255,.05); color: #c8c3d0; font: inherit; font-weight: 700; cursor: pointer; }.mode-tabs button.active { border-color: #efc96f; background: #edc96f; color: #29202f; }.mode-tabs small { opacity: .72; margin-left: 3px; }.records-panel { padding: 22px; }.panel-heading { display: flex; justify-content: space-between; gap: 18px; align-items: flex-start; margin-bottom: 20px; }.panel-heading h2 { margin: 0 0 4px; font-size: 1.2rem; }.panel-heading p { margin: 0; color: #aaa5b8; font-size: .9rem; }.legend { display: flex; flex-wrap: wrap; gap: 12px; color: #aaa5b8; font-size: .78rem; white-space: nowrap; }.legend-hit { color: #f3d28a; }.legend-missed { color: #df8893; }
.year-section + .year-section { margin-top: 27px; }.year-section h3 { display: flex; align-items: baseline; gap: 8px; margin: 0 0 10px; font-size: 1.12rem; }.year-section h3 small { color: #928da0; font-size: .78rem; font-weight: 500; }.month-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }.month-card { min-height: 126px; border: 1px solid rgba(255,255,255,.09); border-radius: 10px; padding: 10px; background: rgba(255,255,255,.025); }.month-card.has-record, .month-card.is-hit { border-color: rgba(234, 201, 111, .3); background: linear-gradient(145deg, rgba(97, 69, 158, .22), rgba(255,255,255,.03)); }.month-card.is-missed { border-color: rgba(211, 109, 126, .28); }.month-card header { display: flex; justify-content: space-between; color: #aaa5b8; font-size: .8rem; font-weight: 700; }.month-card header em { padding: 1px 5px; border-radius: 99px; background: #edc96f; color: #332637; font-size: .67rem; font-style: normal; }.mode-row { display: grid; grid-template-columns: 34px 1fr; align-items: center; column-gap: 5px; min-height: 25px; margin-top: 5px; font-size: .76rem; }.mode-name { color: var(--mode-color); font-size: .67rem; font-weight: 800; }.mode-row b { overflow: hidden; color: #ebe7ed; text-overflow: ellipsis; white-space: nowrap; }.mode-row small { color: #bca2dd; }.mode-row.is-missed b { color: #dc8d98; }.empty { color: #666474; }.single-hit { position: relative; display: grid; gap: 5px; margin-top: 18px; }.single-hit b { font-size: 1.08rem; }.single-hit span { color: #c8b4e4; font-size: .82rem; }.single-hit i { position: absolute; top: 0; right: 0; width: 8px; height: 8px; border-radius: 50%; box-shadow: 0 0 12px currentColor; }.single-missed, .single-empty { margin-top: 24px; color: #dc8d98; font-weight: 700; }.single-empty { color: #666474; font-weight: 500; }
.class-panel { margin-top: 18px; }.hero-bars { display: grid; gap: 10px; max-width: 700px; }.hero-bar { display: grid; grid-template-columns: 64px 1fr 24px; align-items: center; gap: 10px; }.hero-bar > span { color: #d4cedc; font-size: .84rem; font-weight: 700; }.hero-bar > div { height: 9px; overflow: hidden; border-radius: 999px; background: rgba(255,255,255,.1); }.hero-bar i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #7f60d3, #edc96f); }.hero-bar b { color: #f3d28a; font-size: .82rem; text-align: right; }
.month-card.has-record, .month-card.is-hit { border-color: rgba(234, 201, 111, .3); }.month-card.is-missed { border-color: rgba(255,255,255,.09); }.month-card header { color: #c2bdca; font-size: .9rem; }.mode-row { grid-template-columns: 1fr; gap: 2px; margin-top: 8px; }.mode-meta { display: flex; align-items: baseline; gap: 3px; line-height: 1.1; }.mode-name { font-size: .82rem; }.mode-meta small { color: #bca2dd; font-size: .78rem; white-space: nowrap; }.mode-row b { font-size: .98rem; line-height: 1.25; }.mode-row > small { display: none; }.mode-row.is-missed, .single-missed { display: none; }
@media (max-width: 900px) { .summary-grid { grid-template-columns: repeat(3, 1fr); }.month-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } } @media (max-width: 580px) { .legends-page { padding: 28px 14px 50px; }.summary-grid { grid-template-columns: 1fr; gap: 8px; }.summary-card { min-height: 104px; padding: 13px; }.summary-card strong { font-size: 1.45rem; }.records-panel { padding: 15px; }.panel-heading { display: grid; }.month-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }.month-card { min-height: 126px; }.mode-tabs button { padding: 7px 10px; font-size: .82rem; } }
</style>
